======== product-wiki/pack.mjs ========
// Project-aspect standard pack: the self-growing product research wiki
// (compile-once/refine-in-place, cited, dated, isolated behind the reviewed
// product-requirements crossing point). The folder is the classifier: the two
// reserved names (product-requirements/, sample-data/) have fixed meaning;
// everything else under product-wiki/ is wiki space. Fingerprinted by the
// standard's one structural constant — the sink.
import { SINK_README } from './lib.mjs';
import layout from './layout.mjs';
import pageSections from './page-sections.mjs';
import growthLog from './growth-log.mjs';
import sources from './sources.mjs';
import freshness from './freshness.mjs';
import isolation from './isolation.mjs';
import wikiGrowth from './run_daily/wiki-growth.mjs';

export default {
  id: 'product-wiki',
  marker: SINK_README,
  detect: (ctx) => ctx.tracked.includes(SINK_README),
  prose: 'RULES.md',
  // The isolation wall rides the barriers mechanism: this pack requires
  // barriers and CONTRIBUTES the fixed barrier as manifest data
  // (isolation.mjs — pure data, no cross-pack import; pack-independence).
  requires: ['barriers'],
  contributes: { barriers: [isolation] },
  rules: [layout, pageSections, growthLog, sources, freshness],
  run_daily: [wikiGrowth],
};

======== spec-driven-product/pack.mjs ========
// A project-CLASS pack (prose-only, no fingerprint): a product project of this
// class declares it. No detect — declaration is authoritative. The general
// test-trust rules the playbook leans on (see-it-fail, snapshot hygiene,
// re-baselining approval) stay in the writing-tests skill; release mechanics
// stay in the platform's release pack (e.g. chrome-extension-release).
export default {
  id: 'spec-driven-product',
  marker: null,
  detect: null,
  // The product playbook runs its spec as tests — it leans on the framework
  // mechanics the executable-requirements pack carries.
  requires: ['executable-requirements'],
  prose: 'RULES.md',
  rules: [],
};

======== executable-requirements/pack.mjs ========
import featureRequirementsFirst from './feature-requirements-first.mjs';

// The executable-requirements framework standard: the concrete, portable
// conventions — layout, naming, gates, kinds, gallery, determinism — shared by
// every project that runs its spec as tests. The judgment layer (owner-owned
// expecteds, doc-first discipline) is the spec-driven-product pack; this pack
// is the mechanics that implement it. Fingerprinted by the framework's one
// structural constant: the spec file itself.
export default {
  id: 'executable-requirements',
  marker: 'dev/requirements/requirements.md',
  detect: (ctx) => ctx.tracked.includes('dev/requirements/requirements.md'),
  prose: 'RULES.md',
  rules: [featureRequirementsFirst],
};

